func TestAnInkHasAName(emonT *testing.T) {
	port.AssertEq(emonT, sealmark.SmHue(2047903), 10, "the blue of the corpus seals (#1f3f9f) is blue")
	port.AssertEq(emonT, sealmark.SmHue(12591135), 3, "the red of the corpus stamps (#c0201f) is red")
	port.AssertEq(emonT, sealmark.SmHue(1118481), 0, "#111111 is black")
	port.AssertEq(emonT, sealmark.SmHue(8421504), 1, "#808080 is gray")
	port.AssertEq(emonT, sealmark.SmHue(15790320), 2, "#f0f0f0 is white")
	port.AssertEq(emonT, sealmark.SmHue(2138176), 7, "a green is green")
	port.AssertEq(emonT, sealmark.SmHue(16744448), 4, "an orange is orange")
	port.AssertEq(emonT, sealmark.SmHue(6697881), 11, "a purple (#663399) is purple")
	port.AssertEq(emonT, sealmark.SmHue(8388736), 12, "and #800080 (300 degrees) is magenta")
	port.AssertEq(emonT, sealmark.SmHue(-1), -1, "an unknown ink has no name")
	port.AssertEq(emonT, sealmark.SmNameLen(10), 4, "blue has four letters")
	port.AssertEq(emonT, sealmark.SmNames[sealmark.SmNameOff(10)], 98, "which start with b")
	port.AssertEq(emonT, sealmark.SmNameLen(3), 3, "red")
	port.AssertEq(emonT, sealmark.SmNames[sealmark.SmNameOff(3)+2], 100, "ends with d")
}

