func stEx(k int32) int32 {
	// The x offset of the k-th end point of an octagon of radius 3000 (k 0..8; the ninth is the first again).
	if k == 0 {
		return 3000
	}
	if k == 1 {
		return 2121
	}
	if k == 2 {
		return 0
	}
	if k == 3 {
		return -2121
	}
	if k == 4 {
		return -3000
	}
	if k == 5 {
		return -2121
	}
	if k == 6 {
		return 0
	}
	if k == 7 {
		return 2121
	}
	return 3000
}

