	port.AssertEq(emonT, port.CellsAt(out, 2), 3000, "its radius")
	port.AssertEq(emonT, port.CellsAt(out, 3), 0, "its roundness was verified")
	port.AssertEq(emonT, sealmark.SmRingTest(pa, pts, b, out), 0, "an end point pushed 15 per cent of a radius out of the circle: not a ring")
	// a path that kept its box only (more than 128 points): a curve whose box less its stroke is a square
	var c int32 = evidence.PaNew(pa, 1, evidence.PaCurve(), 4850, 4850, 11150, 11150)
	evidence.PaSet(pa, c, evidence.PfFlags(), evidence.PgStroked())
	evidence.PaSet(pa, c, evidence.PfWidth(), 300)
	evidence.PaSet(pa, c, evidence.PfPfirst(), -1)
