func stStroke(pa *port.Cells, pts *port.Cells, x0 int32, y0 int32, segs int32) int32 {
	// An open stroked curve of `segs` Bezier segments from (x0, y0), 800 wide each and 1500 high; answers its row.
	var first int32 = port.CellsLen(pts) / 3
	var k int32 = 0
	var r int32 = evidence.PaNew(pa, 1, evidence.PaCurve(), x0, y0, x0+(segs*800), y0+1500)
	evidence.PtAdd(pts, x0, y0, evidence.PoMove())
	for k < segs {
		evidence.PtAdd(pts, x0+(k*800), y0+1500, evidence.PoCurve())
		evidence.PtAdd(pts, x0+(k*800)+400, y0, evidence.PoCurve())
		evidence.PtAdd(pts, x0+((k+1)*800), y0+700, evidence.PoCurve())
		k += 1
	}
	evidence.PaSet(pa, r, evidence.PfFlags(), evidence.PgStroked())
	evidence.PaSet(pa, r, evidence.PfStroke(), 2047903)
	evidence.PaSet(pa, r, evidence.PfWidth(), 140)
	evidence.PaSet(pa, r, evidence.PfPfirst(), first)
	evidence.PaSet(pa, r, evidence.PfPcount(), 1+(segs*3))
	return r
}

func stText(fw *port.Cells, gl *port.Cells, et *port.Cells, x int32, y int32, a int32, b int32, c int32) int32 {
	// A word of up to three letters, 1200 high, at (x, y); answers its row.
	var ts int32 = port.CellsLen(et)
	var n int32 = 2
	var g int32 = evidence.GlNew(gl, 1, x, y, x+2400, y+1200, a, ts, 1, 0)
	var w int32 = evidence.WdNew(fw, 1, x, y, x+2400, y+1200, x, y+1000, x+2400, y+1000, 0, 0, ts, 2, 0, -1, -1)
	port.CellsPush(et, a)
	port.CellsPush(et, b)
	if c > 0 {
		port.CellsPush(et, c)
		n = 3
	}
	evidence.WdSet(fw, w, 12, n)
	evidence.WdSet(fw, w, evidence.WfGfirst(), g)
	evidence.WdSet(fw, w, evidence.WfGcount(), 1)
	evidence.GlSet(gl, g, evidence.GfFill(), 1118481)
	return w
}

func TestASignatureIsPenStrokesNearACue(emonT *testing.T) {
	var pa *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var sm *port.Cells = port.NewCells()
	stStroke(pa, pts, 10000, 20000, 4)
	stStroke(pa, pts, 10500, 20400, 1)
	// the cue `By:` just to the left, and another word elsewhere
	stText(fw, gl, et, 7200, 20300, 66, 121, 58)
	stText(fw, gl, et, 7200, 40000, 84, 111, 116)
	port.AssertEq(emonT, stFind(pa, pts, gl, fw, et, cg, refs, ow, sm), 1, "two strokes of five segments together and a cue beside them: a signature")
	port.AssertEq(emonT, player.SlGet(sm, 0, 5), player.PlsSignature(), "a signature")
	port.AssertEq(emonT, player.SlGet(sm, 0, 1), 10000, "the box is the union of the strokes")
	port.AssertEq(emonT, player.SlGet(sm, 0, 3), 13200, "to the right edge of the longer")
	port.AssertEq(emonT, player.SlGet(sm, 0, 15), 2047903, "in blue")
	port.AssertEq(emonT, player.SlGet(sm, 0, 14), 0, "a signature has no text")
	// no cue: no signature
	port.CellsDrop(fw, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(gl, 0)
	stText(fw, gl, et, 7200, 20300, 84, 111, 116)
	port.AssertEq(emonT, stFind(pa, pts, gl, fw, et, cg, refs, ow, sm), 0, "without a cue word it is a curve in a figure")
	// a cue four line heights away is too far
	port.CellsDrop(fw, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(gl, 0)
	stText(fw, gl, et, 7200, 30000, 66, 121, 58)
	port.AssertEq(emonT, stFind(pa, pts, gl, fw, et, cg, refs, ow, sm), 0, "a cue far above is none")
}

